import {
  CIRCLE_BATCHING_NAME,
  CIRCLE_BATCHING_VERSION,
  CIRCLE_BATCHING_VERSIONS,
} from './constants';
import { isUsdc } from './config';
import type { CircleBatchingVersion, GatewayPaymentRequirements } from './types';

/**
 * PaymentRequirements-like structure for detection.
 * We only need the `extra` field to detect batching options.
 */
interface PaymentRequirementsLike {
  extra?: Record<string, unknown>;
}

/**
 * Check if this SDK can pay a PaymentRequirements object with batched
 * settlement: it is a batch payment (`isBatchPayment`), and the SDK can sign its
 * `extra.version`. The check does not read the asset: the SDK also refuses to
 * sign version 1 for an asset other than USDC.
 *
 * @param requirements - The payment requirements to check
 * @returns true if this SDK can pay it with batched settlement
 *
 * @example
 * ```typescript
 * import { supportsBatching } from "@circle-fin/x402-batching";
 *
 * if (supportsBatching(paymentRequirements)) {
 *   // This option uses batched settlement (gas-free for users!)
 * }
 * ```
 */
export function supportsBatching<T extends PaymentRequirementsLike>(
  requirements: T,
): requirements is GatewayPaymentRequirements<T> {
  if (!isBatchPayment(requirements)) {
    return false;
  }

  if (typeof requirements.extra?.verifyingContract !== 'string') {
    return false;
  }

  const version = requirements.extra?.version ?? CIRCLE_BATCHING_VERSION;
  return CIRCLE_BATCHING_VERSIONS.includes(version as CircleBatchingVersion);
}

/**
 * Check if a PaymentRequirements object is a batched payment: its
 * `extra.name` is `"GatewayWalletBatched"`, the EIP-712 domain the payer signs.
 * The check does not depend on `extra.version`.
 *
 * Use this to route payments to the appropriate handler, and to tell batched
 * payments apart from standard `exact` payments.
 *
 * @param requirements - The payment requirements to check
 * @returns true if this is a batched payment
 *
 * @example
 * ```typescript
 * import { isBatchPayment, BatchFacilitatorClient } from "@circle-fin/x402-batching/server";
 *
 * const gateway = new BatchFacilitatorClient();
 *
 * // In your facilitator's verify/settle handler:
 * if (isBatchPayment(requirements)) {
 *   return gateway.verify(payload, requirements);
 * }
 * // else: handle with existing on-chain logic
 * ```
 */
export function isBatchPayment(requirements: PaymentRequirementsLike): boolean {
  return requirements.extra?.name === CIRCLE_BATCHING_NAME;
}

/**
 * Get the verifyingContract address from batching requirements.
 *
 * @param requirements - The payment requirements
 * @returns The batch wallet contract address, or undefined if not a batching option
 */
export function getVerifyingContract(
  requirements: PaymentRequirementsLike,
): string | undefined {
  if (!supportsBatching(requirements)) {
    return undefined;
  }

  return requirements.extra.verifyingContract;
}

/**
 * The version of a batch payment the SDK can pay: `extra.version`, or version
 * 1 when it has none.
 */
export function getBatchingVersion(
  requirements: GatewayPaymentRequirements<PaymentRequirementsLike>,
): CircleBatchingVersion {
  return requirements.extra.version ?? CIRCLE_BATCHING_VERSION;
}

/**
 * Whether Gateway accepts the batching version of a batch payment for its
 * asset. A version 1 authorization names no token, so Gateway accepts version
 * 1 for USDC only.
 */
export function isVersionAllowed<
  T extends PaymentRequirementsLike & { network: string; asset: string },
>(requirements: GatewayPaymentRequirements<T>): boolean {
  return (
    getBatchingVersion(requirements) !== CIRCLE_BATCHING_VERSION || isUsdc(requirements)
  );
}
