import type { PaymentPolicy } from '@x402/core/client';
import type { PaymentRequirements } from '@x402/core/types';
import type { GatewayPaymentRequirements } from '../types';
import {
  isBatchPayment,
  supportsBatching,
  getBatchingVersion,
  isVersionAllowed,
} from '../detection';

/**
 * Payment policy that prefers the highest batching version the SDK can sign.
 *
 * Removes every batching requirement except the ones the SDK can pay at the
 * highest version for their token, meaning their network and asset.
 * Requirements that are not batching options stay, and the order does not
 * change.
 *
 * The policy removes a batching requirement that the SDK cannot sign, so
 * `x402Client` would select another offered option. When every requirement
 * is removed the `x402Client.createPaymentPayload()` throws an error.
 *
 * Without the policy, `CompositeEvmScheme` would route a batching requirement that
 * the SDK cannot sign to the `BatchEvmScheme`, and `BatchEvmScheme.createPaymentPayload()`
 * will throw an error.
 *
 * @example
 * ```typescript
 * client.registerPolicy(preferHighestBatchingVersion);
 * ```
 */
export const preferHighestBatchingVersion: PaymentPolicy = (
  _x402Version,
  requirements,
) => {
  const payable = requirements.filter(canPay);

  return requirements.filter((requirement) => {
    if (!isBatchPayment(requirement)) {
      return true;
    }
    if (!canPay(requirement)) {
      return false;
    }
    const batchingVersion = Number(getBatchingVersion(requirement));
    const isHighestVersion = payable.every(
      (other) =>
        !isSameToken(other, requirement) ||
        Number(getBatchingVersion(other)) <= batchingVersion,
    );
    return isHighestVersion;
  });
};

/**
 * The batching option to pay with for an asset on a network: the first
 * batching option for that asset that `preferHighestBatchingVersion` keeps.
 */
export function selectBatchingOption(
  accepts: Array<Record<string, unknown>>,
  network: string,
  asset: string,
): Record<string, unknown> | undefined {
  const options = (accepts as PaymentRequirements[]).filter(
    (opt) =>
      opt.network === network &&
      typeof opt.asset === 'string' &&
      opt.asset.toLowerCase() === asset.toLowerCase() &&
      isBatchPayment(opt),
  );
  return preferHighestBatchingVersion(2, options)[0];
}

function isSameToken(a: PaymentRequirements, b: PaymentRequirements): boolean {
  // x402Client does not validate the 402 response, so any field can be missing.
  // `asset` is the only field that the policy calls a method on.
  return a.network === b.network && a.asset?.toLowerCase() === b.asset?.toLowerCase();
}

function canPay(
  requirement: PaymentRequirements,
): requirement is GatewayPaymentRequirements<PaymentRequirements> {
  return supportsBatching(requirement) && isVersionAllowed(requirement);
}
